function rowsFrom(nodeName) {
  try {
    return $items(nodeName).map(function(item) {
      return item.json;
    });
  } catch (error) {
    throw new Error(`Unable to read rows from ${nodeName}: ${error.message}`);
  }
}

function bySku(rows) {
  const index = new Map();

  for (const row of rows) {
    const prsku = String(row.prsku || "").trim().toUpperCase();
    if (prsku) index.set(prsku, row);
  }

  return index;
}

function numberOrNull(value) {
  if (value === null || value === undefined || value === "") return null;
  const num = Number(value);
  return Number.isFinite(num) ? num : null;
}

function coalesceNumber(value, fallback) {
  const num = numberOrNull(value);
  return num === null ? fallback : num;
}

function isLessThan(left, right) {
  const leftNum = numberOrNull(left);
  const rightNum = numberOrNull(right);
  return leftNum !== null && rightNum !== null && leftNum < rightNum;
}

const baseRows = rowsFrom("SKU Base Details");
const performanceBySku = bySku(rowsFrom("SKU Performance Metrics"));
const qualityPricingBySku = bySku(rowsFrom("SKU PDP Pricing Metrics"));

const assembled = baseRows.map(function(baseRow) {
  const prsku = String(baseRow.prsku || "").trim().toUpperCase();
  const row = {
    ...baseRow,
    ...(performanceBySku.get(prsku) || {}),
    ...(qualityPricingBySku.get(prsku) || {}),
    prsku
  };

  const currentMrpi = numberOrNull(row.current_mrpi);
  const wfRetail = numberOrNull(row.wf_retail);
  const competitorRetail = numberOrNull(row.competitor_retail);
  const avgRank = numberOrNull(row.avg_sku_rank_latest_month);
  const cvrL6m = numberOrNull(row.cvr_l6m);
  const availabilityCurrent = numberOrNull(row.availability_current_month);
  const visitsCurrent = numberOrNull(row.visits_current_month);
  const visitsPrior = numberOrNull(row.visits_prior_month);

  row.wf_competitiveness = currentMrpi === null
    ? "Unknown"
    : currentMrpi > 0
      ? "Uncompetitive"
      : "Competitive";

  if ((currentMrpi !== null && currentMrpi > 0.05) || (wfRetail !== null && competitorRetail !== null && wfRetail > competitorRetail)) {
    row.financials_ask = "Review pricing / Merchandising";
  } else if (coalesceNumber(row.wsc_current_month, 0) < coalesceNumber(row.wsc_prior_month, 0)) {
    row.financials_ask = "Review WSC decline drivers";
  } else {
    row.financials_ask = "Monitor financials";
  }

  if (avgRank !== null && avgRank > 50 && cvrL6m !== null && cvrL6m >= 0.008) {
    row.ads_ask = "Increase spend / improve rank";
  } else if (avgRank !== null && avgRank > 50) {
    row.ads_ask = "Fix rank drivers before scaling spend";
  } else if (cvrL6m !== null && cvrL6m < 0.008) {
    row.ads_ask = "Optimize PDP before more spend";
  } else {
    row.ads_ask = "Optimize spend";
  }

  if (availabilityCurrent !== null && availabilityCurrent < 0.80) {
    row.availability_ask = "Improve Availability";
  } else if (isLessThan(row.availability_current_month, row.availability_prior_month)) {
    row.availability_ask = "Watch availability decline";
  } else {
    row.availability_ask = "Maintain Availability";
  }

  if (visitsCurrent !== null && visitsPrior !== null && visitsCurrent < visitsPrior && avgRank !== null && avgRank > 50) {
    row.visits_ask = "Improve rank to recover visits";
  } else if (visitsCurrent !== null && visitsPrior !== null && visitsCurrent < visitsPrior) {
    row.visits_ask = "Review traffic decline";
  } else if (visitsCurrent !== null && visitsPrior !== null && visitsCurrent > visitsPrior && cvrL6m !== null && cvrL6m < 0.008) {
    row.visits_ask = "Traffic improved; fix CVR";
  } else {
    row.visits_ask = "Monitor visits";
  }

  const pdpFeedback = [];
  if (coalesceNumber(row.five_plus_review_coverage, 0) < 1) pdpFeedback.push("Needs 5+ reviews.");
  if (coalesceNumber(row.required_tag_coverage, 1) < 0.90) pdpFeedback.push("Complete required tags.");
  if (coalesceNumber(row.image_coverage, 1) < 1) pdpFeedback.push("Improve imagery coverage.");
  if (cvrL6m !== null && cvrL6m < 0.008) {
    pdpFeedback.push("Audit PDP: dimensions, material/quality callouts, color accuracy, close-up/scale imagery, shipping promise, price-value.");
  }
  if (currentMrpi !== null && currentMrpi > 0) {
    pdpFeedback.push("Price/value appears uncompetitive; review retail vs market.");
  }
  row.pdp_feedback = pdpFeedback.join(" ");

  return row;
});

assembled.sort(function(left, right) {
  return String(left.requested_supplier || "").localeCompare(String(right.requested_supplier || ""))
    || String(left.requested_issue || "").localeCompare(String(right.requested_issue || ""))
    || String(left.prsku || "").localeCompare(String(right.prsku || ""));
});

return assembled.map(function(row) {
  return { json: row };
});

const rows = $input.all().map(function(item) {
  return item.json;
});

function escapeHtml(value) {
  if (value === null || value === undefined) return "";
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function number(value, digits = 0) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  return num.toLocaleString("en-US", {
    minimumFractionDigits: digits,
    maximumFractionDigits: digits
  });
}

function money(value) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  return "$" + num.toLocaleString("en-US", { maximumFractionDigits: 0 });
}

function percent(value, digits = 1) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  return (num * 100).toFixed(digits) + "%";
}

function pp(value, digits = 1) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  const bps = num * 10000;
  return (bps > 0 ? "+" : "") + bps.toFixed(0) + " bps";
}

function fmt(row, key) {
  const value = row[key];
  if (key.includes("wsc") || key.includes("spend") || key.includes("retail")) return money(value);
  if (key.includes("mom_pp")) return pp(value);
  if (key.includes("pct") || key.includes("coverage") || key.includes("availability") || key.includes("cvr") || key === "current_mrpi") return percent(value);
  if (key.includes("rank")) return number(value, 1);
  if (key.includes("visits")) return number(value);
  if (key.includes("date")) return escapeHtml(value);
  return escapeHtml(value);
}

function cls(row, key) {
  const value = row[key];
  if (key === "is_page_1_latest_month") {
    return value === "Yes" ? "good" : value === "No" ? "bad" : "neutral";
  }
  if (key === "wf_competitiveness") {
    return value === "Competitive" ? "good" : value === "Uncompetitive" ? "bad" : "neutral";
  }
  if (key === "availability_current_month") {
    return Number(value) >= 0.8 ? "good" : "bad";
  }
  if (key === "cvr_l6m") {
    return Number(value) >= 0.008 ? "good" : "bad";
  }
  if (key === "required_tag_coverage") {
    return Number(value) >= 0.9 ? "good" : "bad";
  }
  if (key === "image_coverage" || key === "five_plus_review_coverage") {
    return Number(value) >= 1 ? "good" : "bad";
  }
  if (key === "current_mrpi") {
    return Number(value) > 0 ? "bad" : "good";
  }
  if (key.endsWith("_ask") || key === "pdp_feedback") {
    return "ask";
  }
  return "";
}

const groups = [
  {
    label: "Merch",
    columns: [
      { key: "prsku", label: "PrSKU" },
      { key: "sku_launch_date", label: "SKU Launch Date" },
      { key: "avg_sku_rank_latest_month", label: "SKU Page Rank" },
      { key: "is_page_1_latest_month", label: "Page 1?" }
    ]
  },
  {
    label: "Financials",
    columns: [
      { key: "wsc_current_month", label: "WSC Revenue" },
      { key: "pct_of_sales", label: "% Sales" },
      { key: "wsc_mom_pct", label: "WSC MoM" },
      { key: "financials_ask", label: "ASK" }
    ]
  },
  {
    label: "Ads",
    columns: [
      { key: "ad_spend_ltm", label: "LTM Ad Spend" },
      { key: "ads_ask", label: "Advertising Ask" }
    ]
  },
  {
    label: "Availability",
    columns: [
      { key: "availability_current_month", label: "Month Availability" },
      { key: "availability_ask", label: "Availability Ask" },
      { key: "availability_mom_pct", label: "Availability MoM" }
    ]
  },
  {
    label: "CVR",
    columns: [
      { key: "cvr_l6m", label: "CVR L6M" },
      { key: "cvr_current_month", label: "CVR Month" },
      { key: "cvr_mom_pp", label: "CVR MoM" }
    ]
  },
  {
    label: "Visits",
    columns: [
      { key: "visits_current_month", label: "Visits Month" },
      { key: "visits_prior_month", label: "Visits Prior" },
      { key: "visits_mom_pct", label: "Visits MoM" },
      { key: "visits_ask", label: "Visits Ask" }
    ]
  },
  {
    label: "Merch / PDP",
    columns: [
      { key: "required_tag_coverage", label: "Req Tag Cov" },
      { key: "image_coverage", label: "Image Cov" },
      { key: "five_plus_review_coverage", label: "5+ Reviews" },
      { key: "pdp_feedback", label: "PDP Feedback" }
    ]
  },
  {
    label: "Pricing",
    columns: [
      { key: "item_level_wsi", label: "WSI" },
      { key: "wf_retail", label: "WF Retail" },
      { key: "competitor_retail", label: "Competitor Retail" },
      { key: "competitor_name", label: "Competitor" },
      { key: "current_mrpi", label: "Current MRPI" },
      { key: "wf_competitiveness", label: "WF Competitiveness" }
    ]
  }
];

const flatColumns = groups.flatMap(group => group.columns);

const groupHeader = groups.map(group => `<th class="group" colspan="${group.columns.length}">${escapeHtml(group.label)}</th>`).join("");
const columnHeader = flatColumns.map(col => `<th>${escapeHtml(col.label)}</th>`).join("");
const body = rows.map(row => {
  const cells = flatColumns.map(col => `<td class="${cls(row, col.key)}">${fmt(row, col.key)}</td>`).join("");
  return `<tr>${cells}</tr>`;
}).join("");

const htmlBody = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body {
      font-family: Arial, sans-serif;
      color: #222;
      line-height: 1.35;
    }
    h1 {
      background: #1f4e79;
      color: white;
      padding: 14px;
      border-radius: 6px;
    }
    .summary {
      background: #f3f7fb;
      border-left: 4px solid #1f4e79;
      padding: 12px;
      margin-bottom: 16px;
    }
    .table-wrap {
      overflow-x: auto;
      border: 1px solid #ccc;
    }
    table {
      border-collapse: collapse;
      width: max-content;
      min-width: 100%;
      font-size: 11px;
    }
    th {
      border: 1px solid #999;
      padding: 6px;
      background: #d9eaf7;
      text-align: center;
      white-space: nowrap;
    }
    th.group {
      background: #b7d7ee;
      font-weight: bold;
    }
    td {
      border: 1px solid #ccc;
      padding: 6px;
      vertical-align: top;
      max-width: 260px;
    }
    tr:nth-child(even) td {
      background: #fafafa;
    }
    .good {
      background: #d9ead3 !important;
      color: #1f6f3a;
      font-weight: bold;
    }
    .bad {
      background: #f4cccc !important;
      color: #8a1f11;
      font-weight: bold;
    }
    .neutral {
      background: #fff2cc !important;
      color: #7a5c00;
      font-weight: bold;
    }
    .ask {
      background: #fff2cc !important;
      font-weight: bold;
    }
  </style>
</head>
<body>
  <h1>Cathay & Sunham SKU Scorecard Deep Dive</h1>
  <div class="summary">
    <p><strong>Period:</strong> Latest completed month vs prior month, with L6M CVR and current MRPI competitiveness.</p>
    <p><strong>Rank rule:</strong> lower rank is better; average rank <= 50 is page 1.</p>
    <p><strong>Competitiveness rule:</strong> current MRPI > 0 is marked Uncompetitive.</p>
  </div>
  <div class="table-wrap">
    <table>
      <thead>
        <tr>${groupHeader}</tr>
        <tr>${columnHeader}</tr>
      </thead>
      <tbody>${body}</tbody>
    </table>
  </div>
</body>
</html>
`;

return [{ json: { htmlBody } }];
